#!/usr/bin/env python3
"""
Patch for ai_transformer_predictor.py v9.5 -> v9.6
Fixes:
  1. matmul crash in load() - reinit architecture before loading weights
  2. _is_valid_experience counters + logging
  3. Norm switch at 50 - extra retraining epochs
  4. load_default() counters
  5. save() counters
  6. Shape validation after load
Run: python patch_ai_predictor.py
"""
import os, sys

INPUT = "ai_transformer_predictor.py"
BACKUP = "ai_transformer_predictor_v9.5_backup.py"

REPLACEMENTS = [
    ("        self._factory_target_std = None\n\n    # --- Алиасы",
     "        self._factory_target_std = None\n\n        # v9.6: Счётчики валидации опыта\n        self._n_accepted = 0\n        self._n_rejected = 0\n        self._n_rejected_no_targets = 0\n        self._norms_switched = False\n\n    # --- Алиасы"),
    ("        T_raw = self._denorm_value(targets[0], \"T_plasma\")\n        if T_raw < 1e6:\n            return False\n        pr_raw = self._denorm_value(targets[2], \"pair_rate\")\n        if pr_raw < 1.0:\n            return False\n        return True",
     "        T_raw = self._denorm_value(targets[0], \"T_plasma\")\n        if T_raw < 1e6:\n            self._n_rejected += 1\n            return False\n        pr_raw = self._denorm_value(targets[2], \"pair_rate\")\n        if pr_raw < 1.0:\n            self._n_rejected += 1\n            return False\n        return True"),
    ("        targets = self._extract_targets(history)\n        if targets is None:\n            return False\n        cv = self._extract_features(config)\n        if not self._is_valid_experience(targets):\n            return False\n        self.experience_configs.append(cv.copy())\n        self.experience_targets.append(targets.copy())\n        self.n_experiences += 1\n        return True",
     "        targets = self._extract_targets(history)\n        if targets is None:\n            self._n_rejected_no_targets += 1\n            return False\n        cv = self._extract_features(config)\n        if not self._is_valid_experience(targets):\n            return False\n        self.experience_configs.append(cv.copy())\n        self.experience_targets.append(targets.copy())\n        self.n_experiences += 1\n        self._n_accepted += 1\n        return True"),
    ("    def self_learn(self, config, history):\n        \"\"\"Полный цикл: добавить опыт + обучить. Для обратной совместимости.\"\"\"\n        self.add_experience(config, history)\n        return self.train(config, history)",
     "    def self_learn(self, config, history):\n        \"\"\"Полный цикл: добавить опыт + обучить. Для обратной совместимости.\n        v9.6: логирование статистики опыта.\"\"\"\n        ok = self.add_experience(config, history)\n        total_rej = self._n_rejected + self._n_rejected_no_targets\n        if total_rej > 0 and total_rej % 10 == 0:\n            print(f\"[AutoLearn] exp stats: accepted={self._n_accepted}, \"\n                  f\"rejected(filter)={self._n_rejected}, \"\n                  f\"rejected(no_targets)={self._n_rejected_no_targets}, \"\n                  f\"n_exp={self.n_experiences}\")\n        return self.train(config, history)"),
    ("        # v9.3: Не перезаписываем factory-нормы при < 50 опытах\n        if self.n_experiences >= 50 or self._factory_feature_mean is None:\n            all_c = np.array(self.experience_configs)\n            self.feature_mean = np.mean(all_c, axis=0)\n            self.feature_std = np.maximum(np.std(all_c, axis=0), 0.01)\n            all_t = np.array(self.experience_targets)\n            self.target_mean = np.mean(all_t, axis=0)\n            self.target_std = np.maximum(np.std(all_t, axis=0), 0.01)\n\n        # Простой случайный батч (без стратификации)\n        n_batch = min(128, self.n_experiences)\n        n_epochs = 40",
     "        # v9.6: Не перезаписываем factory-нормы при < 50 опытах\n        norms_just_switched = False\n        if self.n_experiences >= 50 or self._factory_feature_mean is None:\n            if not self._norms_switched and self._factory_feature_mean is not None:\n                norms_just_switched = True\n                self._norms_switched = True\n                print(f\"[AutoLearn] Norm switch at exp={self.n_experiences} — extra retraining\")\n            all_c = np.array(self.experience_configs)\n            self.feature_mean = np.mean(all_c, axis=0)\n            self.feature_std = np.maximum(np.std(all_c, axis=0), 0.01)\n            all_t = np.array(self.experience_targets)\n            self.target_mean = np.mean(all_t, axis=0)\n            self.target_std = np.maximum(np.std(all_t, axis=0), 0.01)\n\n        # Простой случайный батч (без стратификации)\n        n_batch = min(128, self.n_experiences)\n        # v9.6: 80 epochs после смены норм — адаптация весов\n        n_epochs = 80 if norms_just_switched else 40"),
    ("    def load(self, path):\n        if not os.path.exists(path):\n            return False\n        with open(path, 'r') as f:\n            data = json.load(f)\n        if data.get('_model_type') != 'MLP':\n            return False\n        for attr in ['n_features', 'n_targets', 'hidden1', 'hidden2', 'hidden3',\n                      'lr', 'max_grad_norm',\n                      'is_trained', 'n_experiences', 'n_predictions',\n                      'last_error_pct', 'last_error_linear_pct', '_train_steps']:\n            if attr in data:\n                setattr(self, attr, data[attr])\n        self._error_history = data.get('_error_history', [])\n        for attr in ['W1', 'b1', 'W2', 'b2', 'W3', 'b3', 'W4', 'b4',\n                      'feature_mean', 'feature_std', 'target_mean', 'target_std']:\n            setattr(self, attr, np.array(data[attr]))\n        self.experience_configs = [np.array(c) for c in data.get('experience_configs', [])]\n        self.experience_targets = [np.array(t) for t in data.get('experience_targets', [])]\n        # v9.5: восстановление factory-норм из JSON, else — fallback на текущие нормы\n        if '_factory_feature_mean' in data and data['_factory_feature_mean'] is not None:\n            self._factory_feature_mean = np.array(data['_factory_feature_mean'])\n            self._factory_feature_std = np.array(data['_factory_feature_std'])\n            self._factory_target_mean = np.array(data['_factory_target_mean'])\n            self._factory_target_std = np.array(data['_factory_target_std'])\n        else:\n            # fallback для старых чекпоинтов без factory-полей\n            self._factory_feature_mean = self.feature_mean.copy()\n            self._factory_feature_std = self.feature_std.copy()\n            self._factory_target_mean = self.target_mean.copy()\n            self._factory_target_std = self.target_std.copy()\n        return True",
     "    def _validate_shapes(self):\n        \"\"\"v9.6: Проверка консистентности размерностей весов.\"\"\"\n        try:\n            assert self.W1.shape == (self.n_features, self.hidden1)\n            assert self.b1.shape == (self.hidden1,)\n            assert self.W2.shape == (self.hidden1, self.hidden2)\n            assert self.b2.shape == (self.hidden2,)\n            assert self.W3.shape == (self.hidden2, self.hidden3)\n            assert self.b3.shape == (self.hidden3,)\n            assert self.W4.shape == (self.hidden3, self.n_targets)\n            assert self.b4.shape == (self.n_targets,)\n            return True\n        except AssertionError:\n            return False\n\n    def load(self, path):\n        if not os.path.exists(path):\n            return False\n        with open(path, 'r') as f:\n            data = json.load(f)\n        if data.get('_model_type') != 'MLP':\n            return False\n\n        # v9.6: Реинициализируем модель с архитектурой из JSON ПЕРЕД загрузкой весов\n        cfg = {\n            'n_features': int(data.get('n_features', 5)),\n            'n_targets': int(data.get('n_targets', 4)),\n            'hidden1': int(data.get('hidden1', 128)),\n            'hidden2': int(data.get('hidden2', 128)),\n            'hidden3': int(data.get('hidden3', 64)),\n            'lr': float(data.get('lr', 1e-3)),\n        }\n        self.__init__(cfg)\n\n        for attr in ['max_grad_norm', 'is_trained', 'n_experiences', 'n_predictions',\n                      'last_error_pct', 'last_error_linear_pct', '_train_steps']:\n            if attr in data:\n                setattr(self, attr, data[attr])\n        self._error_history = data.get('_error_history', [])\n\n        # v9.6: Загружаем веса с проверкой наличия ключей\n        for attr in ['W1', 'b1', 'W2', 'b2', 'W3', 'b3', 'W4', 'b4',\n                      'feature_mean', 'feature_std', 'target_mean', 'target_std']:\n            if attr in data:\n                setattr(self, attr, np.array(data[attr]))\n            else:\n                print(f\"[AI] load() WARNING: key '{attr}' missing\")\n                return False\n\n        # v9.6: Валидация размерностей\n        if not self._validate_shapes():\n            print(\"[AI] load() FAILED: shape mismatch\")\n            return False\n\n        self.experience_configs = [np.array(c) for c in data.get('experience_configs', [])]\n        self.experience_targets = [np.array(t) for t in data.get('experience_targets', [])]\n\n        if '_factory_feature_mean' in data and data['_factory_feature_mean'] is not None:\n            self._factory_feature_mean = np.array(data['_factory_feature_mean'])\n            self._factory_feature_std = np.array(data['_factory_feature_std'])\n            self._factory_target_mean = np.array(data['_factory_target_mean'])\n            self._factory_target_std = np.array(data['_factory_target_std'])\n        else:\n            self._factory_feature_mean = self.feature_mean.copy()\n            self._factory_feature_std = self.feature_std.copy()\n            self._factory_target_mean = self.target_mean.copy()\n            self._factory_target_std = self.target_std.copy()\n\n        # v9.6: Восстанавливаем счётчики\n        self._n_accepted = self.n_experiences\n        self._n_rejected = 0\n        self._n_rejected_no_targets = 0\n        self._norms_switched = (self.n_experiences >= 50)\n\n        print(f\"[AI] Model loaded: arch={self.hidden1}-{self.hidden2}-{self.hidden3}, \"\n              f\"exp={self.n_experiences}, trained={self.is_trained}\")\n        return True"),
    ("            obj.n_experiences = 0  # v9.5: factory опыт выкинут — считаем с нуля",
     "            obj.n_experiences = 0  # v9.5: factory опыт выкинут — считаем с нуля\n            obj._n_accepted = 0\n            obj._n_rejected = 0\n            obj._n_rejected_no_targets = 0\n            obj._norms_switched = False"),
    ("            '_factory_target_std': self._factory_target_std.tolist() if self._factory_target_std is not None else None,\n        }\n        with open(path, 'w') as f:",
     "            '_factory_target_std': self._factory_target_std.tolist() if self._factory_target_std is not None else None,\n            '_n_accepted': self._n_accepted,\n            '_n_rejected': self._n_rejected,\n            '_n_rejected_no_targets': self._n_rejected_no_targets,\n            '_norms_switched': self._norms_switched,\n        }\n        with open(path, 'w') as f:"),
]

def main():
    if not os.path.exists(INPUT):
        print(f"ERROR: {INPUT} not found in current dir")
        sys.exit(1)
    with open(INPUT, "r", encoding="utf-8") as f:
        code = f.read()
    with open(BACKUP, "w", encoding="utf-8") as f:
        f.write(code)
    print(f"Backup saved: {BACKUP}")
    applied = 0
    for i, (old, new) in enumerate(REPLACEMENTS):
        if old in code:
            code = code.replace(old, new, 1)
            applied += 1
            print(f"  Patch {i+1}/{len(REPLACEMENTS)}: OK")
        else:
            print(f"  Patch {i+1}/{len(REPLACEMENTS)}: SKIP (pattern not found)")
    with open(INPUT, "w", encoding="utf-8") as f:
        f.write(code)
    print(f"\nDone: {applied}/{len(REPLACEMENTS)} patches applied to {INPUT}")

if __name__ == "__main__":
    main()
